import 'package:flutter/material.dart';

const blue = Color(0xFF075985);
const cyan = Color(0xFF129BCB);
const bg = Color(0xFFF4FAFD);
const pale = Color(0xFFE5F6FC);

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const MarineAquaApp());
}

class MarineAquaApp extends StatelessWidget {
  const MarineAquaApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
        debugShowCheckedModeBanner: false,
        title: 'Marine Aqua Technologies',
        theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: bg,
            colorScheme: ColorScheme.fromSeed(seedColor: blue)),
        home: const SplashScreen(),
      );
}

class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});
  @override State<SplashScreen> createState() => _SplashState();
}
class _SplashState extends State<SplashScreen> {
  @override void initState() { super.initState(); Future.delayed(const Duration(seconds: 2), () {
    if (mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const LoginScreen()));
  }); }
  @override Widget build(BuildContext context) => Scaffold(backgroundColor: Colors.white,
    body: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
      Img('assets/products/marine logo.png', 170, 170),
      const SizedBox(height: 22),
      const Text('ఆక్వా సాగులో ప్రతి దశలో... మీకు తోడుగా', textAlign: TextAlign.center,
        style: TextStyle(color: blue,fontSize:18,fontWeight:FontWeight.bold)),
      const SizedBox(height:10), const Text('MARINE AQUA TECHNOLOGIES',style:TextStyle(color:blue,fontSize:17,fontWeight:FontWeight.w800)),
      const SizedBox(height:28), const CircularProgressIndicator(color:cyan),
    ])));
}

class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginState(); }
class _LoginState extends State<LoginScreen> {
  final c=TextEditingController();
  @override void dispose(){c.dispose();super.dispose();}
  void send(){final n=c.text.trim(); if(n.length!=10 || int.tryParse(n)==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('సరైన 10-digit mobile number నమోదు చేయండి')));return;}
    Navigator.push(context,MaterialPageRoute(builder:(_)=>OtpScreen(mobile:n)));}
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white,body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(28),child:Column(children:[
    const SizedBox(height:20), Img('assets/products/marine logo.png',140,140), const SizedBox(height:15),
    const Text('MARINE AQUA TECHNOLOGIES',textAlign:TextAlign.center,style:TextStyle(color:blue,fontSize:23,fontWeight:FontWeight.w900)),
    const SizedBox(height:8),const Text('ఆక్వా సాగులో ప్రతి దశలో... మీకు తోడుగా',textAlign:TextAlign.center,style:TextStyle(color:blue,fontWeight:FontWeight.w600)),
    const SizedBox(height:55),const Align(alignment:Alignment.centerLeft,child:Text('Mobile Login',style:TextStyle(color:blue,fontSize:28,fontWeight:FontWeight.w900))),
    const SizedBox(height:8),const Align(alignment:Alignment.centerLeft,child:Text('Enter your mobile number to continue',style:TextStyle(color:Colors.grey))),
    const SizedBox(height:22),TextField(controller:c,keyboardType:TextInputType.phone,maxLength:10,decoration:InputDecoration(counterText:'',prefixText:'+91  ',hintText:'Mobile number',filled:true,fillColor:bg,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18)),focusedBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:const BorderSide(color:cyan,width:2)))),
    const SizedBox(height:20),SizedBox(width:double.infinity,height:55,child:ElevatedButton(onPressed:send,style:ElevatedButton.styleFrom(backgroundColor:blue,foregroundColor:Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),child:const Text('SEND OTP',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)))),
  ]))));
}

class OtpScreen extends StatefulWidget { final String mobile; const OtpScreen({super.key,required this.mobile}); @override State<OtpScreen> createState()=>_OtpState(); }
