  void verify(){if(c.text.trim()!='123456'){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Test OTP: 123456')));return;} Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const MainNav()),(_)=>false);}
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white,body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(28),child:Column(children:[
    Align(alignment:Alignment.centerLeft,child:IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back))),Img('assets/products/marine logo.png',120,120),const SizedBox(height:15),
    const Text('Verify OTP',style:TextStyle(color:blue,fontSize:30,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('Enter the 6-digit OTP sent to\n+91 ${widget.mobile}',textAlign:TextAlign.center,style:const TextStyle(color:Colors.grey,fontSize:16)),const SizedBox(height:30),
    TextField(controller:c,keyboardType:TextInputType.number,maxLength:6,textAlign:TextAlign.center,style:const TextStyle(fontSize:25,letterSpacing:8,fontWeight:FontWeight.bold),decoration:InputDecoration(counterText:'',hintText:'Enter 6-digit OTP',filled:true,fillColor:bg,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18)))),
    const SizedBox(height:18),SizedBox(width:double.infinity,height:55,child:ElevatedButton(onPressed:verify,style:ElevatedButton.styleFrom(backgroundColor:blue,foregroundColor:Colors.white),child:const Text('VERIFY & CONTINUE',style:TextStyle(fontWeight:FontWeight.bold)))),const SizedBox(height:15),const Text('DEMO OTP: 123456',style:TextStyle(color:cyan,fontWeight:FontWeight.bold))
  ]))));
}

